#include <tora/compat/integer_document.hpp>
#include <iostream>
#include <stdexcept>
using namespace tora;
void require(bool test){if(!test)throw std::runtime_error("Integer5000 codec regression failed");}
int main(){try{auto p=lp::LpProblem::blank(2,2);p.title="Integer \"quoted\" title";p.objective={3.12345678901234,-2};p.constraints={{{2,1},lp::Relation::LessEqual,4.5},{{1,2},lp::Relation::GreaterEqual,-1.25}};auto doc=compat::IntegerDocument::create(compat::ToraLpCodec::create(p,{core::Notation::Scientific,7,3}),{true,false});const auto bytes=doc.encode();require(bytes.substr(0,6)=="5000\r\n");const auto decoded=compat::IntegerDocument::decode(bytes);require(decoded.encode()==bytes);require(decoded.integral==std::vector<bool>({true,false}));require(decoded.lp.problem.objective[0]==p.objective[0]);auto edited=decoded;edited.integral[0]=false;const auto changed=compat::IntegerDocument::decode(edited.encode());require(!changed.integral[0] && !changed.integral[1]);edited.integral[0]=true;require(edited.encode()==bytes);auto uppercase=bytes;const auto end=uppercase.rfind("\"y\"");require(end!=std::string::npos);uppercase.replace(end,3,"\"Y\"");require(compat::IntegerDocument::decode(uppercase).encode()==uppercase);for(auto bad:{std::string("3000\r\n"),bytes.substr(0,bytes.size()-2),bytes+"\"n\"\r\n"}){bool rejected=false;try{(void)compat::IntegerDocument::decode(bad);}catch(const std::exception&){rejected=true;}require(rejected);}std::cout<<"Integer5000 exact roundtrip, precision, doubled quotes, mixed flags, uppercase preservation and framing rejection passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
